(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-090"]={"sura":90,"name_ar":"البلد","name_en":"Al-Balad","verses":20,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":20,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=10\" class=\"link\">90:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:10 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=10\" class=\"link\">90:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:10 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=10\" class=\"link\">90:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:10 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=10\" class=\"link\">90:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:10 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=10\" class=\"link\">90:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:10 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=10\" class=\"link\">90:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:10 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=10\" class=\"link\">90:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:10 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=10\" class=\"link\">90:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:10 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=10\" class=\"link\">90:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:10 ஐ பார்க்கவும்"},"10":{"html":"<strong>மக்காவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>மக்காவின் புனிதத்தின் மீதும் மனிதன் சிரமத்தில் படைக்கப்பட்டது குறித்தும் சத்தியம் செய்தல்</strong><br />\r\n<br />\r\nநகரங்களின் தாயான மக்காவின் மீது சத்தியம் செய்தவனாக, அங்கு வசிப்பவரை (நபியை) விளித்து, மக்காவாசிகள் இஹ்ராம் எனும் புனித நிலையில் இருக்கும்போது அதன் புனிதத்தின் முக்கியத்துவத்தை கவனப்படுத்த, இந்த நகரத்தில் (போரிடுவது) உங்களுக்கு ஆகுமாக்கப்பட்டது என்று அல்லாஹ் கூறுகிறான். முஜாஹித் (ரஹ்) அவர்களிடமிருந்து குஸைஃப் (ரஹ்) அறிவிக்கிறார்கள்: <span class=\"quran-arabic-font text-success\">﴾لاَ</span> <span class=\"quran-arabic-font text-success\">أُقْسِمُ</span> <span class=\"quran-arabic-font text-success\">بِهَـذَا</span> <span class=\"quran-arabic-font text-success\">الْبَلَدِ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (இல்லை! இந்த நகரத்தின் மீது நான் சத்தியம் செய்கிறேன்;) \"இங்கு 'லா' (இல்லை) என்பது அவர்களுக்கு (குறைஷிகளுக்கு) எதிரான மறுப்பாகும். இந்த நகரத்தின் மீது நான் சத்தியம் செய்கிறேன்.\" ஷபீப் பின் பிஷ்ர் (ரஹ்), இக்ரிமா (ரஹ்) வழியாக, இப்னு அப்பாஸ் (ரழி) அவர்கள் பின்வருமாறு கூறியதாக அறிவிக்கிறார்கள்: <span class=\"quran-arabic-font text-success\">﴾لاَ</span> <span class=\"quran-arabic-font text-success\">أُقْسِمُ</span> <span class=\"quran-arabic-font text-success\">بِهَـذَا</span> <span class=\"quran-arabic-font text-success\">الْبَلَدِ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (இல்லை! இந்த நகரத்தின் மீது நான் சத்தியம் செய்கிறேன்;) \"இதன் பொருள் மக்காவாகும்.\" பின்வரும் வசனம் குறித்து: <span class=\"quran-arabic-font text-success\">﴾وَأَنتَ</span> <span class=\"quran-arabic-font text-success\">حِلٌّ</span> <span class=\"quran-arabic-font text-success\">بِهَـذَا</span> <span class=\"quran-arabic-font text-success\">الْبَلَدِ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (மேலும், நீங்கள் இந்த நகரத்தில் அனுமதிக்கப்பட்டவர்.) இப்னு அப்பாஸ் (ரழி) அவர்கள், \"முஹம்மதே (ஸல்)! இதில் (மக்காவில்) போர் செய்வது உங்களுக்கு அனுமதிக்கப்பட்டுள்ளது\" என்று விளக்கமளித்தார்கள். ஸயீத் பின் ஜுபைர், அபூ ஸாலிஹ், அதிய்யா, அத்-தஹ்ஹாக், கத்தாதா, அஸ்-ஸுத்தீ மற்றும் இப்னு ஸைத் (ரஹ்) போன்றோரும் இதே போன்ற கருத்தைத் தெரிவித்துள்ளனர். ஹஸன் அல்-பஸரீ (ரஹ்) அவர்கள் கூறுகையில், \"அல்லாஹ் அவருக்கும் (நபி (ஸல்) அவர்களுக்கும்) ஒரு நாளின் ஒரு குறிப்பிட்ட நேரத்தில் மட்டும் (அங்கு போர் புரிவதை) ஆகுமாக்கினான்\" என்றார்கள். அவர்கள் கூறியதன் விளக்கம் ஆதாரப்பூர்வமான ஒரு ஹதீஸில் இடம் பெற்றுள்ளது. அதில் நபி (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">الْبَلَدَ</span> <span class=\"quran-arabic-font text-success\">حَرَّمَهُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">السَّموَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضَ،</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">حَرَامٌ</span> <span class=\"quran-arabic-font text-success\">بِحُرْمَةِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">يَوْم</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُعْضَدُ</span> <span class=\"quran-arabic-font text-success\">شَجَرُهُ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يُخْتَلَى</span> <span class=\"quran-arabic-font text-success\">خَلَاهُ،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">أُحِلَّتْ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">سَاعَةٌ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">نَهَارٍ،</span> <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">عَادَتْ</span> <span class=\"quran-arabic-font text-success\">حُرْمَتُهَا</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">كَحُرْمَتِهَا</span> <span class=\"quran-arabic-font text-success\">بِالْأَمْسِ،</span> <span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">فَلْيُبَلِّغِ</span> <span class=\"quran-arabic-font text-success\">الشَّاهِدُ</span> <span class=\"quran-arabic-font text-success\">الْغَائِب</span>»<span class=\"quran-arabic-font text-success\">﴿</span> (நிச்சயமாக, அல்லாஹ் வானங்களையும் பூமியையும் படைத்த அன்றே இந்த நகரத்தைப் புனிதமானதாக ஆக்கினான். ஆகவே, இது அல்லாஹ்வின் கட்டளைப்படி மறுமை நாள் வரை புனிதமானதாகும். இதன் மரங்கள் வெட்டப்படக்கூடாது; இதன் புற்கள் பிடுங்கப்படக்கூடாது. ஒரு நாளின் ஒரு சிறு நேரத்தில் மட்டுமே எனக்கு (இதில் போர் செய்ய) அனுமதி வழங்கப்பட்டது. அதன் புனிதம் நேற்று இருந்தது போலவே இன்றும் மீண்டும் நிலைபெற்றுவிட்டது. எனவே, இங்கு இருப்பவர் இல்லாதவர்களுக்கு இச்செய்தியைத் தெரிவிக்கட்டும்.) இந்த ஹதீஸின் மற்றொரு அறிவிப்பில் அவர்கள் (ஸல்) கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span> <span class=\"quran-arabic-font text-success\">تَرَخَّصَ</span> <span class=\"quran-arabic-font text-success\">بِقِتَالِ</span> <span class=\"quran-arabic-font text-success\">رَسُولِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">فَقُولُوا</span>: <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">أَذِنَ</span> <span class=\"quran-arabic-font text-success\">لِرَسُولِهِ</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَأْذَنْ</span> <span class=\"quran-arabic-font text-success\">لَكُم</span>»<span class=\"quran-arabic-font text-success\">﴿</span> (அல்லாஹ்வின் தூதர் (ஸல்) போர் செய்ததை ஒரு காரணமாகக் கொண்டு எவரேனும் (அங்கு போர் செய்ய) முற்பட்டால், அவரிடம் கூறுங்கள்: அல்லாஹ் தனது தூதருக்கு அனுமதி அளித்தான், ஆனால் உங்களுக்கு அனுமதி அளிக்கவில்லை.)<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றான: <span class=\"quran-arabic-font text-success\">﴾وَوَالِدٍ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">وَلَدَ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (பெற்றெடுத்தவர் மீதும், அவர் பெற்றெடுத்தவர் மீதும் சத்தியமாக.) இது குறித்து முஜாஹித், அபூ ஸாலிஹ், கத்தாதா, அத்-தஹ்ஹாக், ஸுஃப்யான் அத்-தவ்ரீ, ஸயீத் பின் ஜுபைர், அஸ்-ஸுத்தீ, ஹஸன் அல்-பஸரீ, குஸைஃப், ஷுரஹ்பீல் பின் ஸஃது (ரஹ்) மற்றும் பலர் கூறுகையில்: \"பெற்றெடுத்தவர் என்பது ஆதம் (அலை) அவர்களையும், அவர் பெற்றெடுத்தவர் என்பது அவரது பிள்ளைகளையும் குறிக்கும்\" என்றனர். முஜாஹித் (ரஹ்) மற்றும் அவரது தோழர்கள் தேர்ந்தெடுத்த இந்தக் கருத்து மிகவும் வலுவானதாகும். அல்லாஹ் முதலில் வசிப்பிடமான நகரத்தின் மீது சத்தியம் செய்துவிட்டு, அதன் பிறகு அதில் வசிப்பவர்களான மனித குலத்தின் தந்தை ஆதம் (அலை) மற்றும் அவரது பிள்ளைகள் மீது சத்தியம் செய்திருப்பது இக்கருத்தை உறுதிப்படுத்துகிறது. அபூ இம்ரான் அல்-ஜவ்னீ (ரஹ்) கூறுகையில், \"இது இப்ராஹீம் (அலை) அவர்களையும் அவர்களது சந்ததியினரையும் குறிக்கும்\" என்றார். இப்னு ஜரீர் (ரஹ்) மற்றும் இப்னு அபீ ஹாதிம் (ரஹ்) ஆகியோரும் இதைத் தம் நூல்களில் பதிவு செய்துள்ளனர். எனினும், இப்னு ஜரீர் (ரஹ்) அவர்கள் இக்கருத்தைப் பொதுவானதாகக் கொண்டு, இது ஒவ்வொரு தந்தை மற்றும் அவரது பிள்ளைகளைக் குறிக்கும் என்ற விளக்கத்தையே பெரிதும் விரும்பினார்கள். இந்த அர்த்தமும் ஏற்றுக்கொள்ளத்தக்கதே. பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾لَقَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَا</span> <span class=\"quran-arabic-font text-success\">الإِنسَـنَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كَبَدٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (நிச்சயமாக நாம் மனிதனை 'கபத்'தில் (சிரமத்தில்) படைத்தோம்.)<br />\r\n<br />\r\n'கபத்' எனும் சொல்லுக்கு இப்னு அப்பாஸ் (ரழி) அவர்கள், \"அவன் சிரமத்திலிருக்கும் நிலையிலேயே படைக்கப்பட்டான், அவனைப் பார்க்கவில்லையா?\" என்று கூறிவிட்டு, அவனது பிறப்பையும் பற்கள் முளைப்பதையும் சுட்டிக்காட்டினார்கள் என அதா (ரஹ்) வழியாக இப்னு அபீ நஜீஹ் மற்றும் ஜுரைஜ் (ரஹ்) ஆகியோர் அறிவிக்கின்றனர். முஜாஹித் (ரஹ்) கூறுகையில்: <span class=\"quran-arabic-font text-success\">﴾فِى</span> <span class=\"quran-arabic-font text-success\">كَبَدٍ﴿</span> (சிரமத்தில்.) \"ஒரு துளி விந்து, பிறகு ஒரு இரத்தக் கட்டி, பிறகு ஒரு தசைப் பிண்டம் என அவனது படைப்பு நிலைகளில் அவன் சிரமங்களைத் தாங்குகிறான்.\" மேலும் அவர் கூறுகையில், இது அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾حَمَلَتْهُ</span> <span class=\"quran-arabic-font text-success\">أُمُّهُ</span> <span class=\"quran-arabic-font text-success\">كُرْهاً</span> <span class=\"quran-arabic-font text-success\">وَوَضَعَتْهُ</span> <span class=\"quran-arabic-font text-success\">كُرْهاً﴿</span> (அவனுடைய தாய் அவனைச் சிரமத்துடனேயே சுமந்தாள்; சிரமத்துடனேயே அவனைப் பெற்றெடுத்தாள்.) (<a href=\"qurandisp.php?sura=46&ayah=15\" class=\"link\">46:15</a>). \"மேலும் அவள் அவனுக்குச் சிரமத்துடன் பாலூட்டுகிறாள், அவனது வாழ்வாதாரத்தைத் தேடுவதும் சிரமமாகவே உள்ளது. இவ்வாறு அவன் இவை அனைத்தையும் சகித்துக்கொள்கிறான்.\" ஸயீத் பின் ஜுபைர் (ரஹ்) கூறுகையில்: <span class=\"quran-arabic-font text-success\">﴾لَقَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَا</span> <span class=\"quran-arabic-font text-success\">الإِنسَـنَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كَبَدٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (நிச்சயமாக நாம் மனிதனைச் சிரமத்தில் படைத்தோம்.) \"சிரமத்திலும் வாழ்வாதாரத்தைத் தேடும் முயற்சியிலும் (படைக்கப்பட்டான்).\" இக்ரிமா (ரஹ்) அவர்கள் \"சிரமத்திலும் நீண்ட துன்பத்திலும்\" என்றும், கத்தாதா (ரஹ்) \"துன்பத்தில்\" என்றும் விளக்கமளித்துள்ளனர். ஹஸன் (ரஹ்) அவர்கள், \"வாழ்க்கையின் மூலம் இவ்வுலகின் கஷ்டங்களையும் மறுமையின் கடுமைகளையும் சகிப்பதே இதன் பொருள்\" என்று கூறியதாக அறிவிக்கப்பட்டுள்ளது.<br />\r\n<br />\r\n<strong>மனிதன் அல்லாஹ்வாலும் அவனது அருட்கொடைகளாலும் சூழப்பட்டுள்ளான்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾أَيَحْسَبُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">لَّن</span> <span class=\"quran-arabic-font text-success\">يَقْدِرَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (தன் மீது எவராலும் அதிகாரம் செலுத்த முடியாது என்று அவன் எண்ணுகிறானா?) ஹஸன் அல்-பஸரீ (ரஹ்) கூறுகையில், \"அதாவது, தனது செல்வத்தை எவராலும் பறிக்க முடியாது என்று அவன் கருதுகிறான்\" என்றார். கத்தாதா (ரஹ்) கூறுகையில், \"ஆதமின் மகன், தன்னிடம் இந்தச் செல்வம் குறித்து - அதை எவ்வாறு சம்பாதித்தான், எவ்வாறு செலவிட்டான் என்று - கேட்கப்படாது என நினைக்கிறான்\" என்றார். அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾يَقُولُ</span> <span class=\"quran-arabic-font text-success\">أَهْلَكْتُ</span> <span class=\"quran-arabic-font text-success\">مَالاً</span> <span class=\"quran-arabic-font text-success\">لُّبَداً</span> <span class=\"quran-arabic-font text-success\">﴿</span> (அவன் கூறுகிறான்: \"ஏராளமான செல்வத்தை நான் அழித்துவிட்டேன்!\") அதாவது, \"நான் பெருமளவு செல்வத்தைச் செலவு செய்துள்ளேன்\" என்று ஆதமின் மகன் கூறுகிறான். முஜாஹித், ஹஸன், கத்தாதா, அஸ்-ஸுத்தீ (ரஹ்) உள்ளிட்டோர் இவ்வாறு கூறியுள்ளனர். <span class=\"quran-arabic-font text-success\">﴾أَيَحْسَبُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">يَرَهُ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (தன்னை எவரும் பார்க்கவில்லை என்று அவன் எண்ணுகிறானா?) முஜாஹித் (ரஹ்) கூறுகையில், \"வல்லமையும் கண்ணியமும் மிக்க அல்லாஹ் தன்னைப் பார்க்கவில்லை என்று அவன் கருதுகிறானா?\" என்றார். முன்னோர்களான ஸலஃபு ஸாலிஹீன்களில் பலரும் இதைப் போன்றே கூறியுள்ளனர். அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">نَجْعَل</span> <span class=\"quran-arabic-font text-success\">لَّهُ</span> <span class=\"quran-arabic-font text-success\">عَيْنَيْنِ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (நாம் அவனுக்கு இரண்டு கண்களை அமைக்கவில்லையா?) அதாவது, அவன் பார்ப்பதற்காக. <span class=\"quran-arabic-font text-success\">﴾وَلِسَاناً﴿</span> (மேலும் ஒரு நாவையும்) அதாவது, அவன் பேசுவதற்காகவும், தனது உள்ளக்கிடக்கையை வெளிப்படுத்துவதற்காகவும். <span class=\"quran-arabic-font text-success\">﴾وَشَفَتَيْنِ﴿</span> (மற்றும் இரண்டு உதடுகளையும்) பேசுவதற்கும், உணவு உண்பதற்கும், அவனது முகத்திற்கும் வாய்க்கும் அழகூட்டுவதற்கும் உதவும் வகையில் (அமைத்தான்).<br />\r\n<br />\r\n<strong>நன்மை தீமையைப் பிரித்தறியும் திறனும் ஒரு அருட்கொடையே</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَهَدَيْنَـهُ</span> <span class=\"quran-arabic-font text-success\">النَّجْدَينِ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (மேலும், நாம் அவனுக்கு இரு வழிகளைக் காட்டினோம்.) இது இரு பாதைகளைக் குறிக்கும். ஸுஃப்யான் அத்-தவ்ரீ (ரஹ்) அவர்கள் ஆஸிம் (ரஹ்) மற்றும் ஸிர் (ரஹ்) வழியாக, அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள், <span class=\"quran-arabic-font text-success\">﴾وَهَدَيْنَـهُ</span> <span class=\"quran-arabic-font text-success\">النَّجْدَينِ</span> <span class=\"quran-arabic-font text-success\">﴿</span> என்பதற்கு \"நன்மை மற்றும் தீமை\" என்று விளக்கமளித்ததாக அறிவிக்கிறார்கள். அலி (ரழி), இப்னு அப்பாஸ் (ரழி), முஜாஹித், இக்ரிமா (ரஹ்), அபூ வாயில் (ரஹ்), அபூ ஸாலிஹ் (ரஹ்), முஹம்மது பின் கஅப் (ரஹ்), அத்-தஹ்ஹாக் (ரஹ்) மற்றும் அதா அல்-குராஸானீ (ரஹ்) உள்ளிட்ட பலரிடமிருந்தும் இதே போன்ற கருத்து அறிவிக்கப்பட்டுள்ளது. இந்த வசனத்திற்கு ஒப்பானதே அல்லாஹ்வின் பின்வரும் வசனமுமாகும்: <span class=\"quran-arabic-font text-success\">﴾إِنَّا</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَا</span> <span class=\"quran-arabic-font text-success\">الإِنسَـنَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">نُّطْفَةٍ</span> <span class=\"quran-arabic-font text-success\">أَمْشَاجٍ</span> <span class=\"quran-arabic-font text-success\">نَّبْتَلِيهِ</span> <span class=\"quran-arabic-font text-success\">فَجَعَلْنَـهُ</span> <span class=\"quran-arabic-font text-success\">سَمِيعاً</span> <span class=\"quran-arabic-font text-success\">بَصِيراً</span> - <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">هَدَيْنَـهُ</span> <span class=\"quran-arabic-font text-success\">السَّبِيلَ</span> <span class=\"quran-arabic-font text-success\">إِمَّا</span> <span class=\"quran-arabic-font text-success\">شَاكِراً</span> <span class=\"quran-arabic-font text-success\">وَإِمَّا</span> <span class=\"quran-arabic-font text-success\">كَفُوراً</span> <span class=\"quran-arabic-font text-success\">﴿</span> (நிச்சயமாக, நாம் மனிதனைச் சோதிப்பதற்காகக் கலப்பான விந்துத்துளியிலிருந்து படைத்தோம்; எனவே அவனைச் செவியுறுபவனாகவும் பார்ப்பவனாகவும் ஆக்கினோம். நிச்சயமாக நாம் அவனுக்கு வழியைக் காட்டினோம்; அவன் நன்றியுள்ளவனாக இருக்கலாம் அல்லது நன்றி மறந்தவனாக இருக்கலாம்.) (<a href=\"qurandisp.php?sura=76&ayah=2\" class=\"link\">76:2</a>-3) மேலும் ஹதீஸில் வந்துள்ளது: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">هُمَا</span> <span class=\"quran-arabic-font text-success\">نَجْدَانِ،</span> <span class=\"quran-arabic-font text-success\">نَجْدُ</span> <span class=\"quran-arabic-font text-success\">الْخَيْرِ</span> <span class=\"quran-arabic-font text-success\">وَنَجْدُ</span> <span class=\"quran-arabic-font text-success\">الشَّرِّ،</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">نَجْدَ</span> <span class=\"quran-arabic-font text-success\">الشَّرِّ</span> <span class=\"quran-arabic-font text-success\">أَحَبَّ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">نَجْدِ</span> <span class=\"quran-arabic-font text-success\">الْخَيْرِ</span>»<span class=\"quran-arabic-font text-success\">﴿</span> (\"அவை (நன்மை, தீமை எனும்) இரு மேட்டுப் பாதைகளாகும். நன்மையின் பாதையைவிடத் தீமையின் பாதை உங்களுக்கு விருப்பமானதாக ஆக்கப்படவில்லை.\")<br />\r\n<br />","text":"மக்காவில் அருளப்பட்டது\n\r\n\n\r\n﴾بِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ ﴿\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nமக்காவின் புனிதத்தின் மீதும் மனிதன் சிரமத்தில் படைக்கப்பட்டது குறித்தும் சத்தியம் செய்தல்\n\r\n\n\r\nநகரங்களின் தாயான மக்காவின் மீது சத்தியம் செய்தவனாக, அங்கு வசிப்பவரை (நபியை) விளித்து, மக்காவாசிகள் இஹ்ராம் எனும் புனித நிலையில் இருக்கும்போது அதன் புனிதத்தின் முக்கியத்துவத்தை கவனப்படுத்த, இந்த நகரத்தில் (போரிடுவது) உங்களுக்கு ஆகுமாக்கப்பட்டது என்று அல்லாஹ் கூறுகிறான். முஜாஹித் (ரஹ்) அவர்களிடமிருந்து குஸைஃப் (ரஹ்) அறிவிக்கிறார்கள்: ﴾لاَ أُقْسِمُ بِهَـذَا الْبَلَدِ ﴿ (இல்லை! இந்த நகரத்தின் மீது நான் சத்தியம் செய்கிறேன்;) \"இங்கு 'லா' (இல்லை) என்பது அவர்களுக்கு (குறைஷிகளுக்கு) எதிரான மறுப்பாகும். இந்த நகரத்தின் மீது நான் சத்தியம் செய்கிறேன்.\" ஷபீப் பின் பிஷ்ர் (ரஹ்), இக்ரிமா (ரஹ்) வழியாக, இப்னு அப்பாஸ் (ரழி) அவர்கள் பின்வருமாறு கூறியதாக அறிவிக்கிறார்கள்: ﴾لاَ أُقْسِمُ بِهَـذَا الْبَلَدِ ﴿ (இல்லை! இந்த நகரத்தின் மீது நான் சத்தியம் செய்கிறேன்;) \"இதன் பொருள் மக்காவாகும்.\" பின்வரும் வசனம் குறித்து: ﴾وَأَنتَ حِلٌّ بِهَـذَا الْبَلَدِ ﴿ (மேலும், நீங்கள் இந்த நகரத்தில் அனுமதிக்கப்பட்டவர்.) இப்னு அப்பாஸ் (ரழி) அவர்கள், \"முஹம்மதே (ஸல்)! இதில் (மக்காவில்) போர் செய்வது உங்களுக்கு அனுமதிக்கப்பட்டுள்ளது\" என்று விளக்கமளித்தார்கள். ஸயீத் பின் ஜுபைர், அபூ ஸாலிஹ், அதிய்யா, அத்-தஹ்ஹாக், கத்தாதா, அஸ்-ஸுத்தீ மற்றும் இப்னு ஸைத் (ரஹ்) போன்றோரும் இதே போன்ற கருத்தைத் தெரிவித்துள்ளனர். ஹஸன் அல்-பஸரீ (ரஹ்) அவர்கள் கூறுகையில், \"அல்லாஹ் அவருக்கும் (நபி (ஸல்) அவர்களுக்கும்) ஒரு நாளின் ஒரு குறிப்பிட்ட நேரத்தில் மட்டும் (அங்கு போர் புரிவதை) ஆகுமாக்கினான்\" என்றார்கள். அவர்கள் கூறியதன் விளக்கம் ஆதாரப்பூர்வமான ஒரு ஹதீஸில் இடம் பெற்றுள்ளது. அதில் நபி (ஸல்) அவர்கள் கூறினார்கள்: ﴾«إِنَّ هَذَا الْبَلَدَ حَرَّمَهُ اللهُ يَوْمَ خَلَقَ السَّموَاتِ وَالْأَرْضَ، فَهُوَ حَرَامٌ بِحُرْمَةِ اللهِ إِلَى يَوْم الْقِيَامَةِ لَا يُعْضَدُ شَجَرُهُ وَلَا يُخْتَلَى خَلَاهُ، وَإِنَّمَا أُحِلَّتْ لِي سَاعَةٌ مِنْ نَهَارٍ، وَقَدْ عَادَتْ حُرْمَتُهَا الْيَوْمَ كَحُرْمَتِهَا بِالْأَمْسِ، أَلَا فَلْيُبَلِّغِ الشَّاهِدُ الْغَائِب»﴿ (நிச்சயமாக, அல்லாஹ் வானங்களையும் பூமியையும் படைத்த அன்றே இந்த நகரத்தைப் புனிதமானதாக ஆக்கினான். ஆகவே, இது அல்லாஹ்வின் கட்டளைப்படி மறுமை நாள் வரை புனிதமானதாகும். இதன் மரங்கள் வெட்டப்படக்கூடாது; இதன் புற்கள் பிடுங்கப்படக்கூடாது. ஒரு நாளின் ஒரு சிறு நேரத்தில் மட்டுமே எனக்கு (இதில் போர் செய்ய) அனுமதி வழங்கப்பட்டது. அதன் புனிதம் நேற்று இருந்தது போலவே இன்றும் மீண்டும் நிலைபெற்றுவிட்டது. எனவே, இங்கு இருப்பவர் இல்லாதவர்களுக்கு இச்செய்தியைத் தெரிவிக்கட்டும்.) இந்த ஹதீஸின் மற்றொரு அறிவிப்பில் அவர்கள் (ஸல்) கூறினார்கள்: ﴾«فَإِنْ أَحَدٌ تَرَخَّصَ بِقِتَالِ رَسُولِ اللهِ فَقُولُوا: إِنَّ اللهَ أَذِنَ لِرَسُولِهِ وَلَمْ يَأْذَنْ لَكُم»﴿ (அல்லாஹ்வின் தூதர் (ஸல்) போர் செய்ததை ஒரு காரணமாகக் கொண்டு எவரேனும் (அங்கு போர் செய்ய) முற்பட்டால், அவரிடம் கூறுங்கள்: அல்லாஹ் தனது தூதருக்கு அனுமதி அளித்தான், ஆனால் உங்களுக்கு அனுமதி அளிக்கவில்லை.)\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றான: ﴾وَوَالِدٍ وَمَا وَلَدَ ﴿ (பெற்றெடுத்தவர் மீதும், அவர் பெற்றெடுத்தவர் மீதும் சத்தியமாக.) இது குறித்து முஜாஹித், அபூ ஸாலிஹ், கத்தாதா, அத்-தஹ்ஹாக், ஸுஃப்யான் அத்-தவ்ரீ, ஸயீத் பின் ஜுபைர், அஸ்-ஸுத்தீ, ஹஸன் அல்-பஸரீ, குஸைஃப், ஷுரஹ்பீல் பின் ஸஃது (ரஹ்) மற்றும் பலர் கூறுகையில்: \"பெற்றெடுத்தவர் என்பது ஆதம் (அலை) அவர்களையும், அவர் பெற்றெடுத்தவர் என்பது அவரது பிள்ளைகளையும் குறிக்கும்\" என்றனர். முஜாஹித் (ரஹ்) மற்றும் அவரது தோழர்கள் தேர்ந்தெடுத்த இந்தக் கருத்து மிகவும் வலுவானதாகும். அல்லாஹ் முதலில் வசிப்பிடமான நகரத்தின் மீது சத்தியம் செய்துவிட்டு, அதன் பிறகு அதில் வசிப்பவர்களான மனித குலத்தின் தந்தை ஆதம் (அலை) மற்றும் அவரது பிள்ளைகள் மீது சத்தியம் செய்திருப்பது இக்கருத்தை உறுதிப்படுத்துகிறது. அபூ இம்ரான் அல்-ஜவ்னீ (ரஹ்) கூறுகையில், \"இது இப்ராஹீம் (அலை) அவர்களையும் அவர்களது சந்ததியினரையும் குறிக்கும்\" என்றார். இப்னு ஜரீர் (ரஹ்) மற்றும் இப்னு அபீ ஹாதிம் (ரஹ்) ஆகியோரும் இதைத் தம் நூல்களில் பதிவு செய்துள்ளனர். எனினும், இப்னு ஜரீர் (ரஹ்) அவர்கள் இக்கருத்தைப் பொதுவானதாகக் கொண்டு, இது ஒவ்வொரு தந்தை மற்றும் அவரது பிள்ளைகளைக் குறிக்கும் என்ற விளக்கத்தையே பெரிதும் விரும்பினார்கள். இந்த அர்த்தமும் ஏற்றுக்கொள்ளத்தக்கதே. பின்னர் அல்லாஹ் கூறுகிறான்: ﴾لَقَدْ خَلَقْنَا الإِنسَـنَ فِى كَبَدٍ ﴿ (நிச்சயமாக நாம் மனிதனை 'கபத்'தில் (சிரமத்தில்) படைத்தோம்.)\n\r\n\n\r\n'கபத்' எனும் சொல்லுக்கு இப்னு அப்பாஸ் (ரழி) அவர்கள், \"அவன் சிரமத்திலிருக்கும் நிலையிலேயே படைக்கப்பட்டான், அவனைப் பார்க்கவில்லையா?\" என்று கூறிவிட்டு, அவனது பிறப்பையும் பற்கள் முளைப்பதையும் சுட்டிக்காட்டினார்கள் என அதா (ரஹ்) வழியாக இப்னு அபீ நஜீஹ் மற்றும் ஜுரைஜ் (ரஹ்) ஆகியோர் அறிவிக்கின்றனர். முஜாஹித் (ரஹ்) கூறுகையில்: ﴾فِى كَبَدٍ﴿ (சிரமத்தில்.) \"ஒரு துளி விந்து, பிறகு ஒரு இரத்தக் கட்டி, பிறகு ஒரு தசைப் பிண்டம் என அவனது படைப்பு நிலைகளில் அவன் சிரமங்களைத் தாங்குகிறான்.\" மேலும் அவர் கூறுகையில், இது அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றதாகும்: ﴾حَمَلَتْهُ أُمُّهُ كُرْهاً وَوَضَعَتْهُ كُرْهاً﴿ (அவனுடைய தாய் அவனைச் சிரமத்துடனேயே சுமந்தாள்; சிரமத்துடனேயே அவனைப் பெற்றெடுத்தாள்.) (46:15). \"மேலும் அவள் அவனுக்குச் சிரமத்துடன் பாலூட்டுகிறாள், அவனது வாழ்வாதாரத்தைத் தேடுவதும் சிரமமாகவே உள்ளது. இவ்வாறு அவன் இவை அனைத்தையும் சகித்துக்கொள்கிறான்.\" ஸயீத் பின் ஜுபைர் (ரஹ்) கூறுகையில்: ﴾لَقَدْ خَلَقْنَا الإِنسَـنَ فِى كَبَدٍ ﴿ (நிச்சயமாக நாம் மனிதனைச் சிரமத்தில் படைத்தோம்.) \"சிரமத்திலும் வாழ்வாதாரத்தைத் தேடும் முயற்சியிலும் (படைக்கப்பட்டான்).\" இக்ரிமா (ரஹ்) அவர்கள் \"சிரமத்திலும் நீண்ட துன்பத்திலும்\" என்றும், கத்தாதா (ரஹ்) \"துன்பத்தில்\" என்றும் விளக்கமளித்துள்ளனர். ஹஸன் (ரஹ்) அவர்கள், \"வாழ்க்கையின் மூலம் இவ்வுலகின் கஷ்டங்களையும் மறுமையின் கடுமைகளையும் சகிப்பதே இதன் பொருள்\" என்று கூறியதாக அறிவிக்கப்பட்டுள்ளது.\n\r\n\n\r\nமனிதன் அல்லாஹ்வாலும் அவனது அருட்கொடைகளாலும் சூழப்பட்டுள்ளான்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: ﴾أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌ ﴿ (தன் மீது எவராலும் அதிகாரம் செலுத்த முடியாது என்று அவன் எண்ணுகிறானா?) ஹஸன் அல்-பஸரீ (ரஹ்) கூறுகையில், \"அதாவது, தனது செல்வத்தை எவராலும் பறிக்க முடியாது என்று அவன் கருதுகிறான்\" என்றார். கத்தாதா (ரஹ்) கூறுகையில், \"ஆதமின் மகன், தன்னிடம் இந்தச் செல்வம் குறித்து - அதை எவ்வாறு சம்பாதித்தான், எவ்வாறு செலவிட்டான் என்று - கேட்கப்படாது என நினைக்கிறான்\" என்றார். அல்லாஹ் கூறினான்: ﴾يَقُولُ أَهْلَكْتُ مَالاً لُّبَداً ﴿ (அவன் கூறுகிறான்: \"ஏராளமான செல்வத்தை நான் அழித்துவிட்டேன்!\") அதாவது, \"நான் பெருமளவு செல்வத்தைச் செலவு செய்துள்ளேன்\" என்று ஆதமின் மகன் கூறுகிறான். முஜாஹித், ஹஸன், கத்தாதா, அஸ்-ஸுத்தீ (ரஹ்) உள்ளிட்டோர் இவ்வாறு கூறியுள்ளனர். ﴾أَيَحْسَبُ أَن لَّمْ يَرَهُ أَحَدٌ ﴿ (தன்னை எவரும் பார்க்கவில்லை என்று அவன் எண்ணுகிறானா?) முஜாஹித் (ரஹ்) கூறுகையில், \"வல்லமையும் கண்ணியமும் மிக்க அல்லாஹ் தன்னைப் பார்க்கவில்லை என்று அவன் கருதுகிறானா?\" என்றார். முன்னோர்களான ஸலஃபு ஸாலிஹீன்களில் பலரும் இதைப் போன்றே கூறியுள்ளனர். அல்லாஹ் கூறினான்: ﴾أَلَمْ نَجْعَل لَّهُ عَيْنَيْنِ ﴿ (நாம் அவனுக்கு இரண்டு கண்களை அமைக்கவில்லையா?) அதாவது, அவன் பார்ப்பதற்காக. ﴾وَلِسَاناً﴿ (மேலும் ஒரு நாவையும்) அதாவது, அவன் பேசுவதற்காகவும், தனது உள்ளக்கிடக்கையை வெளிப்படுத்துவதற்காகவும். ﴾وَشَفَتَيْنِ﴿ (மற்றும் இரண்டு உதடுகளையும்) பேசுவதற்கும், உணவு உண்பதற்கும், அவனது முகத்திற்கும் வாய்க்கும் அழகூட்டுவதற்கும் உதவும் வகையில் (அமைத்தான்).\n\r\n\n\r\nநன்மை தீமையைப் பிரித்தறியும் திறனும் ஒரு அருட்கொடையே\n\r\n\n\r\n﴾وَهَدَيْنَـهُ النَّجْدَينِ ﴿ (மேலும், நாம் அவனுக்கு இரு வழிகளைக் காட்டினோம்.) இது இரு பாதைகளைக் குறிக்கும். ஸுஃப்யான் அத்-தவ்ரீ (ரஹ்) அவர்கள் ஆஸிம் (ரஹ்) மற்றும் ஸிர் (ரஹ்) வழியாக, அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள், ﴾وَهَدَيْنَـهُ النَّجْدَينِ ﴿ என்பதற்கு \"நன்மை மற்றும் தீமை\" என்று விளக்கமளித்ததாக அறிவிக்கிறார்கள். அலி (ரழி), இப்னு அப்பாஸ் (ரழி), முஜாஹித், இக்ரிமா (ரஹ்), அபூ வாயில் (ரஹ்), அபூ ஸாலிஹ் (ரஹ்), முஹம்மது பின் கஅப் (ரஹ்), அத்-தஹ்ஹாக் (ரஹ்) மற்றும் அதா அல்-குராஸானீ (ரஹ்) உள்ளிட்ட பலரிடமிருந்தும் இதே போன்ற கருத்து அறிவிக்கப்பட்டுள்ளது. இந்த வசனத்திற்கு ஒப்பானதே அல்லாஹ்வின் பின்வரும் வசனமுமாகும்: ﴾إِنَّا خَلَقْنَا الإِنسَـنَ مِن نُّطْفَةٍ أَمْشَاجٍ نَّبْتَلِيهِ فَجَعَلْنَـهُ سَمِيعاً بَصِيراً - إِنَّا هَدَيْنَـهُ السَّبِيلَ إِمَّا شَاكِراً وَإِمَّا كَفُوراً ﴿ (நிச்சயமாக, நாம் மனிதனைச் சோதிப்பதற்காகக் கலப்பான விந்துத்துளியிலிருந்து படைத்தோம்; எனவே அவனைச் செவியுறுபவனாகவும் பார்ப்பவனாகவும் ஆக்கினோம். நிச்சயமாக நாம் அவனுக்கு வழியைக் காட்டினோம்; அவன் நன்றியுள்ளவனாக இருக்கலாம் அல்லது நன்றி மறந்தவனாக இருக்கலாம்.) (76:2-3) மேலும் ஹதீஸில் வந்துள்ளது: ﴾«هُمَا نَجْدَانِ، نَجْدُ الْخَيْرِ وَنَجْدُ الشَّرِّ، فَمَا جَعَلَ نَجْدَ الشَّرِّ أَحَبَّ إِلَيْكُمْ مِنْ نَجْدِ الْخَيْرِ»﴿ (\"அவை (நன்மை, தீமை எனும்) இரு மேட்டுப் பாதைகளாகும். நன்மையின் பாதையைவிடத் தீமையின் பாதை உங்களுக்கு விருப்பமானதாக ஆக்கப்படவில்லை.\")"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=20\" class=\"link\">90:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:20 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=20\" class=\"link\">90:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:20 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=20\" class=\"link\">90:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:20 ஐ பார்க்கவும்"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=20\" class=\"link\">90:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:20 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=20\" class=\"link\">90:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:20 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=20\" class=\"link\">90:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:20 ஐ பார்க்கவும்"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=20\" class=\"link\">90:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:20 ஐ பார்க்கவும்"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=20\" class=\"link\">90:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:20 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=90&ayah=20\" class=\"link\">90:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 90:20 ஐ பார்க்கவும்"},"20":{"html":"<strong>நன்மையின் பாதையில் செல்வதற்குரிய ஊக்கம்</strong><br />\r\n<br />\r\nஇப்னு ஸைத் (ரஹ்) கூறினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">اقْتَحَمَ</span> <span class=\"quran-arabic-font text-success\">الْعَقَبَةَ</span><br />\r\n(ஆனால் அவன் அந்தச் செங்குத்தான பாதையில் நுழையவில்லை.) \"இதன் பொருள், ஈடேற்றமும் நன்மையும் கொண்ட பாதையில் அவன் செல்ல வேண்டாமா? என்பதாகும். பிறகு அல்லாஹ் இந்தப் பாதையைப் பற்றி பின்வருமாறு விளக்குகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَدْرَاكَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">الْعَقَبَةُ</span> - <span class=\"quran-arabic-font text-success\">فَكُّ</span> <span class=\"quran-arabic-font text-success\">رَقَبَةٍ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">إِطْعَامٌ</span><br />\r\n(மேலும், அந்தச் செங்குத்தான பாதை என்னவென்று உமக்கு எது அறிவிக்கும்? அது ஓர் அடிமையை விடுதலை செய்வது அல்லது உணவளிப்பதாகும்.)\" இமாம் அஹ்மத் அவர்கள் ஸயீத் பின் மர்ஜானா வாயிலாகப் பதிவு செய்துள்ளனர்: அபூ ஹுரைரா (ரழி) அவர்கள் கூறக் கேட்டேன், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَعْتَقَ</span> <span class=\"quran-arabic-font text-success\">رَقَبَةً</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنَةً</span> <span class=\"quran-arabic-font text-success\">أَعْتَقَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">إِرْبٍ</span> <span class=\"quran-arabic-font text-success\">أَيْ</span> <span class=\"quran-arabic-font text-success\">عُضْوٍ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">إِرْبًا</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَيُعْتِقُ</span> <span class=\"quran-arabic-font text-success\">بِالْيَدِ</span> <span class=\"quran-arabic-font text-success\">الْيَدَ،</span> <span class=\"quran-arabic-font text-success\">وَبِالرِّجْلِ</span> <span class=\"quran-arabic-font text-success\">الرِّجْلَ،</span> <span class=\"quran-arabic-font text-success\">وَبِالْفَرْجِ</span> <span class=\"quran-arabic-font text-success\">الْفَرْج</span>»<br />\r\n(யார் ஒரு நம்பிக்கையாளரான (முஃமினான) அடிமையை விடுதலை செய்கிறாரோ, அந்த அடிமையின் ஒவ்வொரு உறுப்புக்கும் பதிலாக அவருடைய ஒவ்வொரு உறுப்பையும் அல்லாஹ் நரக நெருப்பிலிருந்து விடுதலை செய்வான். எந்த அளவிற்கு என்றால், ஒரு கைக்கு ஒரு கையையும், ஒரு காலுக்கு ஒரு காலையும், ஒரு மறைவுறுப்புக்கு ஒரு மறைவுறுப்பையும் அவன் (அல்லாஹ்) நரகிலிருந்து விடுதலை செய்வான்.)<br />\r\n<br />\r\nபிறகு அலீ பின் அல்-ஹுசைன் (ரஹ்) அவர்கள் (ஸயீத் அவர்களிடம்), \"இதை நீங்கள் அபூ ஹுரைரா (ரழி) அவர்களிடமிருந்து கேட்டீர்களா?\" என்று கேட்டார்கள். அதற்கு ஸயீத் \"ஆம்\" என்று பதிலளித்தார். உடனே அலீ பின் அல்-ஹுசைன் (ரஹ்) அவர்கள் தமக்குச் சொந்தமான, தம் பணியாளர்களிலேயே மிகச் சுறுசுறுப்பான ஓர் அடிமைச் சிறுவனிடம், \"முதர்ரிஃபை அழையுங்கள்!\" என்று கூறினார்கள். அந்த அடிமை அவர் முன் கொண்டு வரப்பட்டபோது, \"நீ செல், அல்லாஹ்வின் திருப்திக்காக நீ விடுதலை செய்யப்பட்டாய்\" என்று கூறினார்கள். அல்-புகாரி, முஸ்லிம், அத்-திர்மிதி, அன்-நஸாயீ ஆகிய அனைவரும் இந்த ஹதீஸை ஸயீத் பின் மர்ஜானா வாயிலாகவே பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் அம்ர் பின் அபஸா (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளனர்: நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">بَنَى</span> <span class=\"quran-arabic-font text-success\">مَسْجِدًا</span> <span class=\"quran-arabic-font text-success\">لِيُذْكَرَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">بَنَى</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بَيْتًا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَعْتَقَ</span> <span class=\"quran-arabic-font text-success\">نَفْسًا</span> <span class=\"quran-arabic-font text-success\">مُسْلِمَةً</span> <span class=\"quran-arabic-font text-success\">كَانَتْ</span> <span class=\"quran-arabic-font text-success\">فِدْيَتَهُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">شَابَ</span> <span class=\"quran-arabic-font text-success\">شَيْبَةً</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْإِسْلَامِ</span> <span class=\"quran-arabic-font text-success\">كَانَتْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">نُورًا</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَة</span>»<br />\r\n(அல்லாஹ்வின் பெயர் நினைவு கூரப்படுவதற்காக எவர் ஒரு மஸ்ஜிதைக் கட்டுகிறாரோ, அல்லாஹ் அவருக்குச் சொர்க்கத்தில் ஒரு வீட்டைக் கட்டுவான்; எவர் ஒரு முஸ்லிமை விடுதலை செய்கிறாரோ, அது அவரை நரகத்திலிருந்து மீட்கும் ஈட்டுத் தொகையாக அமையும்; இஸ்லாத்தில் இருக்கும் நிலையில் எவருக்கு நரை முடிகிறதோ, அது அவருக்கு மறுமை நாளில் ஓர் ஒளியாக அமையும்.)<br />\r\n<br />\r\nமற்றொரு அறிவிப்பாளர் தொடரின்படி, இமாம் அஹ்மத் அவர்கள் அபூ உமாமா (ரழி) வழியாக அம்ர் பின் அபஸா (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளனர்: அஸ்-ஸுலமி அவர்கள் அவரிடம் (அம்ர் (ரழி) அவர்களிடம்), \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடமிருந்து நீங்கள் கேட்ட, எவ்விதக் குறைவோ தவறோ இல்லாத ஒரு ஹதீஸை எங்களுக்கு அறிவியுங்கள்\" என்று கேட்டார். அதற்கு அம்ர் (ரழி) கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறுவதை நான் கேட்டேன்:<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">وُلِدَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">ثَلَاثَةُ</span> <span class=\"quran-arabic-font text-success\">أَوْلَادٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْإِسْلَامِ</span> <span class=\"quran-arabic-font text-success\">فَمَاتُوا</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَبْلُغُوا</span> <span class=\"quran-arabic-font text-success\">الْحِنْثَ</span> <span class=\"quran-arabic-font text-success\">أَدْخَلَهُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ</span> <span class=\"quran-arabic-font text-success\">بِفَضْلِ</span> <span class=\"quran-arabic-font text-success\">رَحْمَتِهِ</span> <span class=\"quran-arabic-font text-success\">إِيَّاهُمْ،</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">شَابَ</span> <span class=\"quran-arabic-font text-success\">شَيْبَةً</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">كَانَتْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">نُورًا</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ،</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">رَمَى</span> <span class=\"quran-arabic-font text-success\">بِسَهْمٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">بَلَغَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الْعَدُوَّ</span> <span class=\"quran-arabic-font text-success\">أَصَابَ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَخْطَأَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">عِتْقُ</span> <span class=\"quran-arabic-font text-success\">رَقَبَةٍ،</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَعْتَقَ</span> <span class=\"quran-arabic-font text-success\">رَقَبَةً</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنَةً</span> <span class=\"quran-arabic-font text-success\">أَعْتَقَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">عُضْوٍ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">عُضْوًا</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النَّارِ،</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَنْفَقَ</span> <span class=\"quran-arabic-font text-success\">زَوْجَيْنِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لِلْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">ثَمَانِيَةَ</span> <span class=\"quran-arabic-font text-success\">أَبْوَابٍ</span> <span class=\"quran-arabic-font text-success\">يُدْخِلُهُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَيِّ</span> <span class=\"quran-arabic-font text-success\">بَابٍ</span> <span class=\"quran-arabic-font text-success\">شَاءَ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span>»<br />\r\n(எவருக்கு இஸ்லாத்தில் மூன்று குழந்தைகள் பிறந்து, அவர்கள் பருவ வயதை அடைவதற்கு முன்பே இறந்து விடுகிறார்களோ, அவர்கள் மீது தான் கொண்டுள்ள கருணையினால் அல்லாஹ் அவரைச் சொர்க்கத்தில் நுழையச் செய்வான். அல்லாஹ்வின் பாதையில் (அறப்போரில்) எவருக்கு நரை முடிகிறதோ, அது அவருக்கு மறுமை நாளில் ஒளியாக இருக்கும். அல்லாஹ்வின் பாதையில் (அறப்போரில்) ஒருவர் ஓர் அம்பை எய்து, அது எதிரியைச் சென்றடைந்தால் - அது இலக்கைத் தாக்கினாலும் சரி, தவறினாலும் சரி - அவருக்கு ஓர் அடிமையை விடுதலை செய்த நன்மை கிடைக்கும். யார் ஒரு நம்பிக்கையாளரான (முஃமினான) அடிமையை விடுதலை செய்கிறாரோ, அந்த அடிமையின் ஒவ்வொரு உறுப்புக்கும் பதிலாக அவருடைய ஒவ்வொரு உறுப்பையும் அல்லாஹ் நரகத்திலிருந்து விடுதலை செய்வான். அல்லாஹ்வின் பாதையில் (அறப்போருக்காக) எவர் இரு சவாரி விலங்குகளை வழங்குகிறாரோ, அவருக்குச் சொர்க்கத்தின் எட்டு வாசல்களும் திறக்கப்படும்; அவற்றில் அவர் விரும்பும் எந்த வாசல் வழியாகவும் அல்லாஹ் அவரை நுழையச் செய்வான்.)\" இமாம் அஹ்மத் இந்த ஹதீஸை வலுவான பல்வேறு அறிவிப்பாளர் தொடர்கள் வழியாகப் பதிவு செய்துள்ளனர். எல்லாப் புகழும் அல்லாஹ்வுக்கே.<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">إِطْعَامٌ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">ذِى</span> <span class=\"quran-arabic-font text-success\">مَسْغَبَةٍ</span><br />\r\n(அல்லது கடும் பசி நிலவும் நாளில் உணவளிப்பது.) இப்னு அப்பாஸ் (ரழி) அவர்கள், \"மஸ்கபா என்பது பசி\" என்று கூறினார்கள். இக்ரிமா, முஜாஹித், அத்-தஹ்ஹாக், கதாதா (ரஹ்) மற்றும் பலர் இதே கருத்தைக் கூறியுள்ளனர். 'ஸஃக்ப்' (Saghb) என்ற சொல்லுக்குப் பசி என்று பொருள்.<br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">يَتِيماً</span><br />\r\n(ஓர் அநாதைக்கு) அதாவது, இத்தகைய பசி மிகுந்த நாளில் ஓர் அநாதைக்கு உணவளிப்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَا</span> <span class=\"quran-arabic-font text-success\">مَقْرَبَةٍ</span><br />\r\n(நெருங்கிய உறவுடையவன்.) அதாவது, அவனுடன் உறவுமுறை கொண்டவன். இப்னு அப்பாஸ், இக்ரிமா, அல்-ஹஸன், அத்-தஹ்ஹாக் மற்றும் அஸ்-ஸுத்தி (ரஹ்) ஆகியோர் இதைக் கூறியுள்ளனர். இமாம் அஹ்மத் அவர்கள் ஸல்மான் பின் ஆமிர் (ரழி) வாயிலாகப் பதிவு செய்துள்ள ஹதீஸும் இதைப் போன்றதே. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறக் கேட்டதாக ஸல்மான் பின் ஆமிர் (ரழி) கூறினார்கள்:<br />\r\n«<span class=\"quran-arabic-font text-success\">الصَّدَقَةُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْمِسْكِينِ</span> <span class=\"quran-arabic-font text-success\">صَدَقَةٌ</span> <span class=\"quran-arabic-font text-success\">وَعَلَى</span> <span class=\"quran-arabic-font text-success\">ذِي</span> <span class=\"quran-arabic-font text-success\">الرَّحِمِ</span> <span class=\"quran-arabic-font text-success\">اثْنَتَانِ</span>: <span class=\"quran-arabic-font text-success\">صَدَقَةٌ</span> <span class=\"quran-arabic-font text-success\">وَصِلَة</span>»<br />\r\n(ஏழைக்குத் தர்மம் செய்வது ஒரு தர்மமாகக் கருதப்படும். ஆனால் உறவினருக்குத் தர்மம் செய்வது இரண்டு நன்மைகளைத் தரும்: ஒன்று தர்மம், மற்றொன்று உறவைப் பேணுதல்.) அத்-திர்மிதி மற்றும் அன்-நஸாயீ ஆகிய இருவரும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்; இதன் அறிவிப்பாளர் தொடர் ஆதாரப்பூர்வமானது.<br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مِسْكِيناً</span> <span class=\"quran-arabic-font text-success\">ذَا</span> <span class=\"quran-arabic-font text-success\">مَتْرَبَةٍ</span><br />\r\n(அல்லது வறுமையினால் மண்ணோடு ஒட்டியிருக்கும் ஏழைக்கு (தா மத்ரபா).) அதாவது, வறுமையில் வாடும், பரிதாபத்திற்குரிய, மண்ணில் கிடக்கும் நிலையில் உள்ள ஏழை. இது கடும் வறுமையைக் குறிக்கிறது. இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், \"தா மத்ரபா என்பது தெருவில் வீடின்றி, மண்ணிலிருந்து தன்னைப் பாதுகாத்துக் கொள்ள எதுவுமின்றி அவல நிலையில் இருப்பவரைக் குறிக்கும்\" என்றார்கள்.<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span><br />\r\n(பிறகு அவர் நம்பிக்கை கொண்டவர்களில் ஒருவரானார்.) அதாவது, இத்தகைய அழகிய மற்றும் தூய நற்பண்புகளுடன், அவர் தம் உள்ளத்தில் அல்லாஹ்விடமிருந்து அதற்கான நற்கூலியை ஆதரவு வைத்த ஓர் இறைநம்பிக்கையாளராகவும் இருந்தார். இதையே அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَرَادَ</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةَ</span> <span class=\"quran-arabic-font text-success\">وَسَعَى</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">سَعْيَهَا</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنٌ</span> <span class=\"quran-arabic-font text-success\">فَأُولَـئِكَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">سَعْيُهُم</span> <span class=\"quran-arabic-font text-success\">مَّشْكُورًا</span><br />\r\n(யார் மறுமையை விரும்பி, அதற்காக வேண்டிய முயற்சிகளை மேற்கொண்டு, நம்பிக்கையாளராகவும் (முஃமின்) இருக்கிறாரோ, அத்தகையோரின் முயற்சி (அல்லாஹ்விடம்) அங்கீகரிக்கப்பட்டதாகும்.) (<a href=\"qurandisp.php?sura=17&ayah=19\" class=\"link\">17:19</a>)<br />\r\n<br />\r\nஅல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">عَمِلَ</span> <span class=\"quran-arabic-font text-success\">صَـلِحاً</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ذَكَرٍ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أُنْثَى</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنٌ</span><br />\r\n(ஆணோ பெண்ணோ, நம்பிக்கையாளராக (முஃமின்) இருக்கும் நிலையில் யார் நற்செயல்களைச் செய்கிறாரோ...) (<a href=\"qurandisp.php?sura=16&ayah=97\" class=\"link\">16:97</a>)<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَوَاصَوْاْ</span> <span class=\"quran-arabic-font text-success\">بِالصَّبْرِ</span> <span class=\"quran-arabic-font text-success\">وَتَوَاصَوْاْ</span> <span class=\"quran-arabic-font text-success\">بِالْمَرْحَمَةِ</span><br />\r\n(மேலும் ஒருவருக்கொருவர் பொறுமையைக் கடைப்பிடிக்கவும், ஒருவருக்கொருவர் கருணை காட்டவும் அறிவுறுத்திக் கொண்டனர்.) அதாவது, அவர் நற்செயல்கள் புரியும் நம்பிக்கையாளர்களில் ஒருவராக இருந்தார். மேலும் மக்களால் ஏற்படும் துன்பங்களைப் பொறுத்துக் கொள்ளவும், பிறர் மீது கருணை காட்டவும் ஒருவருக்கொருவர் அறிவுறுத்துபவராகவும் இருந்தார். இது கண்ணியமிக்க இந்த ஹதீஸைப் போன்றது:<br />\r\n«<span class=\"quran-arabic-font text-success\">الرَّاحِمُونَ</span> <span class=\"quran-arabic-font text-success\">يَرْحَمُهُمُ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمنُ،</span> <span class=\"quran-arabic-font text-success\">ارْحَمُوا</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">يَرْحَمْكُمْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّمَاء</span>»<br />\r\n(கருணை காட்டுபவர்கள் மீது மகா கருணையாளன் (அல்லாஹ்) கருணை காட்டுவான். பூமியில் உள்ளவர்கள் மீது கருணை காட்டுங்கள்; வானத்திலிருப்பவன் உங்கள் மீது கருணை காட்டுவான்.)<br />\r\n<br />\r\nமற்றொரு ஹதீஸில் அவர்கள் கூறினார்கள்:<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَرْحَمُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَرْحَمِ</span> <span class=\"quran-arabic-font text-success\">النَّاس</span>»<br />\r\n(மக்களுக்குக் கருணை காட்டாதவர் மீது அல்லாஹ் கருணை காட்ட மாட்டான்.)<br />\r\n<br />\r\nஅபூ தாவூத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) வாயிலாகப் பதிவு செய்துள்ளனர்: (நபி (ஸல்) அவர்கள் கூறினார்கள்),<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَرْحَمْ</span> <span class=\"quran-arabic-font text-success\">صَغِيرَنَا</span> <span class=\"quran-arabic-font text-success\">وَيَعْرِفْ</span> <span class=\"quran-arabic-font text-success\">حَقَّ</span> <span class=\"quran-arabic-font text-success\">كَبِيرِنَا</span> <span class=\"quran-arabic-font text-success\">فَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">مِنَّا</span>»<br />\r\n(யார் நமது சிறியவர்கள் மீது கருணை காட்டவில்லையோ, நமது பெரியவர்களின் உரிமையை அறிந்து கொள்ளவில்லையோ, அவர் நம்மைச் சார்ந்தவர் அல்லர்.)<br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">أَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">الْمَيْمَنَةِ</span><br />\r\n(இவர்களே வலப்பக்கத்தோர் ஆவர்.) அதாவது, இத்தகைய நற்பண்புகளைக் கொண்டவர்களே வலப்பக்கத் தோழர்கள் ஆவர்.<br />\r\n<br />\r\n<strong>இடப்பக்கத் தோழர்களும் அவர்களுக்கான தண்டனையும்</strong><br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">بِآيَاتِنَا</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">أَصْحَابُ</span> <span class=\"quran-arabic-font text-success\">الْمَشْأَمَةِ</span><br />\r\n(ஆனால் எவர் நமது வசனங்களை நிராகரித்தார்களோ, அவர்கள் இடப்பக்கத் தோழர்கள் ஆவர்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">نَارٌ</span> <span class=\"quran-arabic-font text-success\">مُّؤْصَدَةٌ</span><br />\r\n(அவர்கள் மீது நெருப்பு மூடப்பட்டிருக்கும் (முஃஸதா).) அதாவது, அந்த நெருப்பு அவர்களைச் சூழ்ந்து மூடப்பட்டிருக்கும்; அதிலிருந்து தப்பிக்கவோ வெளியேறவோ அவர்களுக்கு வழியே இருக்காது. அபூ ஹுரைரா, இப்னு அப்பாஸ், இக்ரிமா, ஸயீத் பின் ஜுபைர், முஜாஹித், முஹம்மது பின் கஅப் அல்-குரழீ, அதிய்யா அல்-அவ்ஃபீ, அல்-ஹஸன், கதாதா மற்றும் அஸ்-ஸுத்தி (ரஹ்) ஆகிய அனைவரும் பின்வருமாறு விளக்கம் அளித்துள்ளனர்:<br />\r\n<span class=\"quran-arabic-font text-success\">مُؤْصَدَةٌ</span><br />\r\n(முஃஸதா.) \"இதன் பொருள் மூடப்பட்டது.\" இப்னு அப்பாஸ் (ரழி) அவர்கள், \"அதன் கதவுகள் அடைக்கப்பட்டிருக்கும்\" என்றார்.<br />\r\n<br />\r\nஅத்-தஹ்ஹாக் (ரஹ்) அவர்கள் கூறினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">مُؤْصَدَةٌ</span><br />\r\n(முஃஸதா.) \"அது அவர்கள் மீது முற்றிலும் மூடப்பட்டிருக்கும், அதற்கு கதவுகள் ஏதும் இருக்காது.\"<br />\r\n<br />\r\nகதாதா (ரஹ்) அவர்கள் கூறினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">مُؤْصَدَةٌ</span><br />\r\n(முஃஸதா.) \"அது மூடப்பட்டிருக்கும்; அதில் ஒளியோ, தப்பிக்க ஏதேனும் பிளவோ, அல்லது அங்கிருந்து வெளியேறும் வழியோ என்றென்றும் இருக்காது.\"<br />\r\n<br />\r\nஇத்துடன் ஸூரத்துல் பலதின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் அருளும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />\r\n<br />\r\n<br />","text":"நன்மையின் பாதையில் செல்வதற்குரிய ஊக்கம்\n\r\n\n\r\nஇப்னு ஸைத் (ரஹ்) கூறினார்கள்:\n\r\nفَلَا اقْتَحَمَ الْعَقَبَةَ\n\r\n(ஆனால் அவன் அந்தச் செங்குத்தான பாதையில் நுழையவில்லை.) \"இதன் பொருள், ஈடேற்றமும் நன்மையும் கொண்ட பாதையில் அவன் செல்ல வேண்டாமா? என்பதாகும். பிறகு அல்லாஹ் இந்தப் பாதையைப் பற்றி பின்வருமாறு விளக்குகிறான்:\n\r\nوَمَآ أَدْرَاكَ مَا الْعَقَبَةُ - فَكُّ رَقَبَةٍ أَوْ إِطْعَامٌ\n\r\n(மேலும், அந்தச் செங்குத்தான பாதை என்னவென்று உமக்கு எது அறிவிக்கும்? அது ஓர் அடிமையை விடுதலை செய்வது அல்லது உணவளிப்பதாகும்.)\" இமாம் அஹ்மத் அவர்கள் ஸயீத் பின் மர்ஜானா வாயிலாகப் பதிவு செய்துள்ளனர்: அபூ ஹுரைரா (ரழி) அவர்கள் கூறக் கேட்டேன், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n«مَنْ أَعْتَقَ رَقَبَةً مُؤْمِنَةً أَعْتَقَ اللهُ بِكُلِّ إِرْبٍ أَيْ عُضْوٍ مِنْهَا إِرْبًا مِنْهُ مِنَ النَّارِ حَتَّى إِنَّهُ لَيُعْتِقُ بِالْيَدِ الْيَدَ، وَبِالرِّجْلِ الرِّجْلَ، وَبِالْفَرْجِ الْفَرْج»\n\r\n(யார் ஒரு நம்பிக்கையாளரான (முஃமினான) அடிமையை விடுதலை செய்கிறாரோ, அந்த அடிமையின் ஒவ்வொரு உறுப்புக்கும் பதிலாக அவருடைய ஒவ்வொரு உறுப்பையும் அல்லாஹ் நரக நெருப்பிலிருந்து விடுதலை செய்வான். எந்த அளவிற்கு என்றால், ஒரு கைக்கு ஒரு கையையும், ஒரு காலுக்கு ஒரு காலையும், ஒரு மறைவுறுப்புக்கு ஒரு மறைவுறுப்பையும் அவன் (அல்லாஹ்) நரகிலிருந்து விடுதலை செய்வான்.)\n\r\n\n\r\nபிறகு அலீ பின் அல்-ஹுசைன் (ரஹ்) அவர்கள் (ஸயீத் அவர்களிடம்), \"இதை நீங்கள் அபூ ஹுரைரா (ரழி) அவர்களிடமிருந்து கேட்டீர்களா?\" என்று கேட்டார்கள். அதற்கு ஸயீத் \"ஆம்\" என்று பதிலளித்தார். உடனே அலீ பின் அல்-ஹுசைன் (ரஹ்) அவர்கள் தமக்குச் சொந்தமான, தம் பணியாளர்களிலேயே மிகச் சுறுசுறுப்பான ஓர் அடிமைச் சிறுவனிடம், \"முதர்ரிஃபை அழையுங்கள்!\" என்று கூறினார்கள். அந்த அடிமை அவர் முன் கொண்டு வரப்பட்டபோது, \"நீ செல், அல்லாஹ்வின் திருப்திக்காக நீ விடுதலை செய்யப்பட்டாய்\" என்று கூறினார்கள். அல்-புகாரி, முஸ்லிம், அத்-திர்மிதி, அன்-நஸாயீ ஆகிய அனைவரும் இந்த ஹதீஸை ஸயீத் பின் மர்ஜானா வாயிலாகவே பதிவு செய்துள்ளனர்.\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் அம்ர் பின் அபஸா (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளனர்: நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n«مَنْ بَنَى مَسْجِدًا لِيُذْكَرَ اللهُ فِيهِ بَنَى اللهُ لَهُ بَيْتًا فِي الْجَنَّةِ وَمَنْ أَعْتَقَ نَفْسًا مُسْلِمَةً كَانَتْ فِدْيَتَهُ مِنْ جَهَنَّمَ وَمَنْ شَابَ شَيْبَةً فِي الْإِسْلَامِ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَة»\n\r\n(அல்லாஹ்வின் பெயர் நினைவு கூரப்படுவதற்காக எவர் ஒரு மஸ்ஜிதைக் கட்டுகிறாரோ, அல்லாஹ் அவருக்குச் சொர்க்கத்தில் ஒரு வீட்டைக் கட்டுவான்; எவர் ஒரு முஸ்லிமை விடுதலை செய்கிறாரோ, அது அவரை நரகத்திலிருந்து மீட்கும் ஈட்டுத் தொகையாக அமையும்; இஸ்லாத்தில் இருக்கும் நிலையில் எவருக்கு நரை முடிகிறதோ, அது அவருக்கு மறுமை நாளில் ஓர் ஒளியாக அமையும்.)\n\r\n\n\r\nமற்றொரு அறிவிப்பாளர் தொடரின்படி, இமாம் அஹ்மத் அவர்கள் அபூ உமாமா (ரழி) வழியாக அம்ர் பின் அபஸா (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளனர்: அஸ்-ஸுலமி அவர்கள் அவரிடம் (அம்ர் (ரழி) அவர்களிடம்), \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடமிருந்து நீங்கள் கேட்ட, எவ்விதக் குறைவோ தவறோ இல்லாத ஒரு ஹதீஸை எங்களுக்கு அறிவியுங்கள்\" என்று கேட்டார். அதற்கு அம்ர் (ரழி) கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறுவதை நான் கேட்டேன்:\n\r\n«مَنْ وُلِدَ لَهُ ثَلَاثَةُ أَوْلَادٍ فِي الْإِسْلَامِ فَمَاتُوا قَبْلَ أَنْ يَبْلُغُوا الْحِنْثَ أَدْخَلَهُ اللهُ الْجَنَّةَ بِفَضْلِ رَحْمَتِهِ إِيَّاهُمْ، وَمَنْ شَابَ شَيْبَةً فِي سَبِيلِ اللهِ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ، وَمَنْ رَمَى بِسَهْمٍ فِي سَبِيلِ اللهِ بَلَغَ بِهِ الْعَدُوَّ أَصَابَ أَوْ أَخْطَأَ كَانَ لَهُ عِتْقُ رَقَبَةٍ، وَمَنْ أَعْتَقَ رَقَبَةً مُؤْمِنَةً أَعْتَقَ اللهُ بِكُلِّ عُضْوٍ مِنْهُ عُضْوًا مِنْهُ مِنَ النَّارِ، وَمَنْ أَنْفَقَ زَوْجَيْنِ فِي سَبِيلِ اللهِ فَإِنَّ لِلْجَنَّةِ ثَمَانِيَةَ أَبْوَابٍ يُدْخِلُهُ اللهُ مِنْ أَيِّ بَابٍ شَاءَ مِنْهَا»\n\r\n(எவருக்கு இஸ்லாத்தில் மூன்று குழந்தைகள் பிறந்து, அவர்கள் பருவ வயதை அடைவதற்கு முன்பே இறந்து விடுகிறார்களோ, அவர்கள் மீது தான் கொண்டுள்ள கருணையினால் அல்லாஹ் அவரைச் சொர்க்கத்தில் நுழையச் செய்வான். அல்லாஹ்வின் பாதையில் (அறப்போரில்) எவருக்கு நரை முடிகிறதோ, அது அவருக்கு மறுமை நாளில் ஒளியாக இருக்கும். அல்லாஹ்வின் பாதையில் (அறப்போரில்) ஒருவர் ஓர் அம்பை எய்து, அது எதிரியைச் சென்றடைந்தால் - அது இலக்கைத் தாக்கினாலும் சரி, தவறினாலும் சரி - அவருக்கு ஓர் அடிமையை விடுதலை செய்த நன்மை கிடைக்கும். யார் ஒரு நம்பிக்கையாளரான (முஃமினான) அடிமையை விடுதலை செய்கிறாரோ, அந்த அடிமையின் ஒவ்வொரு உறுப்புக்கும் பதிலாக அவருடைய ஒவ்வொரு உறுப்பையும் அல்லாஹ் நரகத்திலிருந்து விடுதலை செய்வான். அல்லாஹ்வின் பாதையில் (அறப்போருக்காக) எவர் இரு சவாரி விலங்குகளை வழங்குகிறாரோ, அவருக்குச் சொர்க்கத்தின் எட்டு வாசல்களும் திறக்கப்படும்; அவற்றில் அவர் விரும்பும் எந்த வாசல் வழியாகவும் அல்லாஹ் அவரை நுழையச் செய்வான்.)\" இமாம் அஹ்மத் இந்த ஹதீஸை வலுவான பல்வேறு அறிவிப்பாளர் தொடர்கள் வழியாகப் பதிவு செய்துள்ளனர். எல்லாப் புகழும் அல்லாஹ்வுக்கே.\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\nأَوْ إِطْعَامٌ فِى يَوْمٍ ذِى مَسْغَبَةٍ\n\r\n(அல்லது கடும் பசி நிலவும் நாளில் உணவளிப்பது.) இப்னு அப்பாஸ் (ரழி) அவர்கள், \"மஸ்கபா என்பது பசி\" என்று கூறினார்கள். இக்ரிமா, முஜாஹித், அத்-தஹ்ஹாக், கதாதா (ரஹ்) மற்றும் பலர் இதே கருத்தைக் கூறியுள்ளனர். 'ஸஃக்ப்' (Saghb) என்ற சொல்லுக்குப் பசி என்று பொருள்.\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்:\n\r\nيَتِيماً\n\r\n(ஓர் அநாதைக்கு) அதாவது, இத்தகைய பசி மிகுந்த நாளில் ஓர் அநாதைக்கு உணவளிப்பதாகும்.\n\r\n\n\r\nذَا مَقْرَبَةٍ\n\r\n(நெருங்கிய உறவுடையவன்.) அதாவது, அவனுடன் உறவுமுறை கொண்டவன். இப்னு அப்பாஸ், இக்ரிமா, அல்-ஹஸன், அத்-தஹ்ஹாக் மற்றும் அஸ்-ஸுத்தி (ரஹ்) ஆகியோர் இதைக் கூறியுள்ளனர். இமாம் அஹ்மத் அவர்கள் ஸல்மான் பின் ஆமிர் (ரழி) வாயிலாகப் பதிவு செய்துள்ள ஹதீஸும் இதைப் போன்றதே. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறக் கேட்டதாக ஸல்மான் பின் ஆமிர் (ரழி) கூறினார்கள்:\n\r\n«الصَّدَقَةُ عَلَى الْمِسْكِينِ صَدَقَةٌ وَعَلَى ذِي الرَّحِمِ اثْنَتَانِ: صَدَقَةٌ وَصِلَة»\n\r\n(ஏழைக்குத் தர்மம் செய்வது ஒரு தர்மமாகக் கருதப்படும். ஆனால் உறவினருக்குத் தர்மம் செய்வது இரண்டு நன்மைகளைத் தரும்: ஒன்று தர்மம், மற்றொன்று உறவைப் பேணுதல்.) அத்-திர்மிதி மற்றும் அன்-நஸாயீ ஆகிய இருவரும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்; இதன் அறிவிப்பாளர் தொடர் ஆதாரப்பூர்வமானது.\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்:\n\r\nأَوْ مِسْكِيناً ذَا مَتْرَبَةٍ\n\r\n(அல்லது வறுமையினால் மண்ணோடு ஒட்டியிருக்கும் ஏழைக்கு (தா மத்ரபா).) அதாவது, வறுமையில் வாடும், பரிதாபத்திற்குரிய, மண்ணில் கிடக்கும் நிலையில் உள்ள ஏழை. இது கடும் வறுமையைக் குறிக்கிறது. இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், \"தா மத்ரபா என்பது தெருவில் வீடின்றி, மண்ணிலிருந்து தன்னைப் பாதுகாத்துக் கொள்ள எதுவுமின்றி அவல நிலையில் இருப்பவரைக் குறிக்கும்\" என்றார்கள்.\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\nثُمَّ كَانَ مِنَ الَّذِينَ ءَامَنُواْ\n\r\n(பிறகு அவர் நம்பிக்கை கொண்டவர்களில் ஒருவரானார்.) அதாவது, இத்தகைய அழகிய மற்றும் தூய நற்பண்புகளுடன், அவர் தம் உள்ளத்தில் அல்லாஹ்விடமிருந்து அதற்கான நற்கூலியை ஆதரவு வைத்த ஓர் இறைநம்பிக்கையாளராகவும் இருந்தார். இதையே அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\nوَمَنْ أَرَادَ الْآخِرَةَ وَسَعَى لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌ فَأُولَـئِكَ كَانَ سَعْيُهُم مَّشْكُورًا\n\r\n(யார் மறுமையை விரும்பி, அதற்காக வேண்டிய முயற்சிகளை மேற்கொண்டு, நம்பிக்கையாளராகவும் (முஃமின்) இருக்கிறாரோ, அத்தகையோரின் முயற்சி (அல்லாஹ்விடம்) அங்கீகரிக்கப்பட்டதாகும்.) (17:19)\n\r\n\n\r\nஅல்லாஹ் மேலும் கூறுகிறான்:\n\r\nمَنْ عَمِلَ صَـلِحاً مِّن ذَكَرٍ أَوْ أُنْثَى وَهُوَ مُؤْمِنٌ\n\r\n(ஆணோ பெண்ணோ, நம்பிக்கையாளராக (முஃமின்) இருக்கும் நிலையில் யார் நற்செயல்களைச் செய்கிறாரோ...) (16:97)\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\nوَتَوَاصَوْاْ بِالصَّبْرِ وَتَوَاصَوْاْ بِالْمَرْحَمَةِ\n\r\n(மேலும் ஒருவருக்கொருவர் பொறுமையைக் கடைப்பிடிக்கவும், ஒருவருக்கொருவர் கருணை காட்டவும் அறிவுறுத்திக் கொண்டனர்.) அதாவது, அவர் நற்செயல்கள் புரியும் நம்பிக்கையாளர்களில் ஒருவராக இருந்தார். மேலும் மக்களால் ஏற்படும் துன்பங்களைப் பொறுத்துக் கொள்ளவும், பிறர் மீது கருணை காட்டவும் ஒருவருக்கொருவர் அறிவுறுத்துபவராகவும் இருந்தார். இது கண்ணியமிக்க இந்த ஹதீஸைப் போன்றது:\n\r\n«الرَّاحِمُونَ يَرْحَمُهُمُ الرَّحْمنُ، ارْحَمُوا مَنْ فِي الْأَرْضِ يَرْحَمْكُمْ مَنْ فِي السَّمَاء»\n\r\n(கருணை காட்டுபவர்கள் மீது மகா கருணையாளன் (அல்லாஹ்) கருணை காட்டுவான். பூமியில் உள்ளவர்கள் மீது கருணை காட்டுங்கள்; வானத்திலிருப்பவன் உங்கள் மீது கருணை காட்டுவான்.)\n\r\n\n\r\nமற்றொரு ஹதீஸில் அவர்கள் கூறினார்கள்:\n\r\n«لَا يَرْحَمُ اللهُ مَنْ لَا يَرْحَمِ النَّاس»\n\r\n(மக்களுக்குக் கருணை காட்டாதவர் மீது அல்லாஹ் கருணை காட்ட மாட்டான்.)\n\r\n\n\r\nஅபூ தாவூத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) வாயிலாகப் பதிவு செய்துள்ளனர்: (நபி (ஸல்) அவர்கள் கூறினார்கள்),\n\r\n«مَنْ لَمْ يَرْحَمْ صَغِيرَنَا وَيَعْرِفْ حَقَّ كَبِيرِنَا فَلَيْسَ مِنَّا»\n\r\n(யார் நமது சிறியவர்கள் மீது கருணை காட்டவில்லையோ, நமது பெரியவர்களின் உரிமையை அறிந்து கொள்ளவில்லையோ, அவர் நம்மைச் சார்ந்தவர் அல்லர்.)\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்:\n\r\nأُوْلَـئِكَ أَصْحَـبُ الْمَيْمَنَةِ\n\r\n(இவர்களே வலப்பக்கத்தோர் ஆவர்.) அதாவது, இத்தகைய நற்பண்புகளைக் கொண்டவர்களே வலப்பக்கத் தோழர்கள் ஆவர்.\n\r\n\n\r\nஇடப்பக்கத் தோழர்களும் அவர்களுக்கான தண்டனையும்\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்:\n\r\nوَالَّذِينَ كَفَرُواْ بِآيَاتِنَا هُمْ أَصْحَابُ الْمَشْأَمَةِ\n\r\n(ஆனால் எவர் நமது வசனங்களை நிராகரித்தார்களோ, அவர்கள் இடப்பக்கத் தோழர்கள் ஆவர்.)\n\r\n\n\r\nعَلَيْهِمْ نَارٌ مُّؤْصَدَةٌ\n\r\n(அவர்கள் மீது நெருப்பு மூடப்பட்டிருக்கும் (முஃஸதா).) அதாவது, அந்த நெருப்பு அவர்களைச் சூழ்ந்து மூடப்பட்டிருக்கும்; அதிலிருந்து தப்பிக்கவோ வெளியேறவோ அவர்களுக்கு வழியே இருக்காது. அபூ ஹுரைரா, இப்னு அப்பாஸ், இக்ரிமா, ஸயீத் பின் ஜுபைர், முஜாஹித், முஹம்மது பின் கஅப் அல்-குரழீ, அதிய்யா அல்-அவ்ஃபீ, அல்-ஹஸன், கதாதா மற்றும் அஸ்-ஸுத்தி (ரஹ்) ஆகிய அனைவரும் பின்வருமாறு விளக்கம் அளித்துள்ளனர்:\n\r\nمُؤْصَدَةٌ\n\r\n(முஃஸதா.) \"இதன் பொருள் மூடப்பட்டது.\" இப்னு அப்பாஸ் (ரழி) அவர்கள், \"அதன் கதவுகள் அடைக்கப்பட்டிருக்கும்\" என்றார்.\n\r\n\n\r\nஅத்-தஹ்ஹாக் (ரஹ்) அவர்கள் கூறினார்கள்:\n\r\nمُؤْصَدَةٌ\n\r\n(முஃஸதா.) \"அது அவர்கள் மீது முற்றிலும் மூடப்பட்டிருக்கும், அதற்கு கதவுகள் ஏதும் இருக்காது.\"\n\r\n\n\r\nகதாதா (ரஹ்) அவர்கள் கூறினார்கள்:\n\r\nمُؤْصَدَةٌ\n\r\n(முஃஸதா.) \"அது மூடப்பட்டிருக்கும்; அதில் ஒளியோ, தப்பிக்க ஏதேனும் பிளவோ, அல்லது அங்கிருந்து வெளியேறும் வழியோ என்றென்றும் இருக்காது.\"\n\r\n\n\r\nஇத்துடன் ஸூரத்துல் பலதின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் அருளும் அல்லாஹ்வுக்கே உரியது."}}};})(self);
